import { Component, OnInit } from '@angular/core';
import { FormControl } from '@angular/forms';
import { Router } from '@angular/router';
import { PageEvent } from '@angular/material/paginator';
import { MatDialog } from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { debounceTime, distinctUntilChanged } from 'rxjs/operators';
import { ProductService, Product } from './product.service';
import { ProductFormDialogComponent } from './components/product-form-dialog/product-form-dialog.component';
import { ConfirmDialogComponent } from '../../shared/components/confirm-dialog/confirm-dialog.component';

type StockFilterValue = 'all' | 'in' | 'low' | 'out';

@Component({
  selector: 'app-products',
  templateUrl: './products.component.html',
  styleUrls: ['./products.component.css']
})
export class ProductsComponent implements OnInit {
  products: Product[] = [];
  isLoading = false;
  errorMessage = '';

  totalResults = 0;
  pageSize = 12;
  currentPage = 0;

  readonly categories = [
    'Electrónica',
    'Ropa',
    'Alimentos',
    'Hogar',
    'Deportes',
    'Libros',
    'Juguetes',
    'Salud',
    'Automotriz',
    'Otros'
  ];

  readonly sortOptions = [
    { value: 'createdAt:desc', label: 'Más recientes' },
    { value: 'name:asc', label: 'Nombre (A-Z)' },
    { value: 'name:desc', label: 'Nombre (Z-A)' },
    { value: 'price:asc', label: 'Precio: menor a mayor' },
    { value: 'price:desc', label: 'Precio: mayor a menor' },
    { value: 'stock:desc', label: 'Mayor stock' }
  ];

  readonly stockOptions: Array<{ value: StockFilterValue; label: string }> = [
    { value: 'all', label: 'Todos' },
    { value: 'in', label: 'En stock' },
    { value: 'low', label: 'Stock bajo' },
    { value: 'out', label: 'Sin stock' }
  ];

  searchControl = new FormControl('', { nonNullable: true });
  categoryFilter = new FormControl('all', { nonNullable: true });
  stockFilter = new FormControl<StockFilterValue>('all', { nonNullable: true });
  sortControl = new FormControl('createdAt:desc', { nonNullable: true });

  constructor(
    private productService: ProductService,
    private dialog: MatDialog,
    private snackBar: MatSnackBar,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.setupFilters();
    this.loadProducts();
  }

  setupFilters(): void {
    this.searchControl.valueChanges.pipe(
      debounceTime(300),
      distinctUntilChanged()
    ).subscribe(() => {
      this.currentPage = 0;
      this.loadProducts();
    });

    this.categoryFilter.valueChanges.pipe(
      distinctUntilChanged()
    ).subscribe(() => {
      this.currentPage = 0;
      this.loadProducts();
    });

    this.stockFilter.valueChanges.pipe(
      distinctUntilChanged()
    ).subscribe(() => {
      this.currentPage = 0;
      this.loadProducts();
    });

    this.sortControl.valueChanges.pipe(
      distinctUntilChanged()
    ).subscribe(() => {
      this.currentPage = 0;
      this.loadProducts();
    });
  }

  loadProducts(): void {
    this.isLoading = true;
    this.errorMessage = '';

    this.productService.getProducts({
      page: this.currentPage + 1,
      limit: this.pageSize,
      sortBy: this.sortControl.value,
      name: this.searchControl.value,
      category: this.categoryFilter.value !== 'all' ? this.categoryFilter.value : undefined,
      stockStatus: this.stockFilter.value
    }).subscribe({
      next: (response) => {
        const filteredResults = this.applyClientSideFallbackFilters(response.results);

        this.products = filteredResults;
        this.totalResults = this.shouldUseFilteredCount()
          ? filteredResults.length
          : response.totalResults;
        this.isLoading = false;
      },
      error: (err) => {
        console.error('Error cargando productos:', err);
        this.errorMessage = 'No se pudieron cargar los productos. Verificá que el servidor esté activo.';
        this.isLoading = false;
      }
    });
  }

  applyClientSideFallbackFilters(products: Product[]): Product[] {
    const searchTerm = this.searchControl.value.trim().toLowerCase();
    const selectedCategory = this.categoryFilter.value;
    const selectedStock = this.stockFilter.value;

    return products.filter(product => {
      const matchesSearch = !searchTerm || [
        product.name,
        product.description,
        product.category
      ]
        .filter(Boolean)
        .some(value => String(value).toLowerCase().includes(searchTerm));

      const matchesCategory = selectedCategory === 'all' || product.category === selectedCategory;
      const matchesStock = selectedStock === 'all' || this.getStockStatus(product.stock) === selectedStock;

      return matchesSearch && matchesCategory && matchesStock;
    });
  }

  shouldUseFilteredCount(): boolean {
    return !!this.searchControl.value.trim()
      || this.categoryFilter.value !== 'all'
      || this.stockFilter.value !== 'all';
  }

  onPageChange(event: PageEvent): void {
    this.currentPage = event.pageIndex;
    this.pageSize = event.pageSize;
    this.loadProducts();
  }

  clearFilters(): void {
    this.searchControl.setValue('', { emitEvent: false });
    this.categoryFilter.setValue('all', { emitEvent: false });
    this.stockFilter.setValue('all', { emitEvent: false });
    this.sortControl.setValue('createdAt:desc', { emitEvent: false });
    this.currentPage = 0;
    this.loadProducts();
    this.snackBar.open('Filtros limpiados', 'Cerrar', { duration: 2000 });
  }

  openCreateDialog(): void {
    const ref = this.dialog.open(ProductFormDialogComponent, {
      width: '520px',
      data: { mode: 'create' }
    });

    ref.afterClosed().subscribe(created => {
      if (created) {
        this.snackBar.open('Producto creado correctamente', 'Cerrar', { duration: 3000 });
        this.loadProducts();
      }
    });
  }

  editProduct(product: Product): void {
    const ref = this.dialog.open(ProductFormDialogComponent, {
      width: '520px',
      data: { mode: 'edit', product }
    });

    ref.afterClosed().subscribe(updated => {
      if (updated) {
        this.snackBar.open('Producto actualizado correctamente', 'Cerrar', { duration: 3000 });
        this.loadProducts();
      }
    });
  }

  deleteProduct(product: Product): void {
    const ref = this.dialog.open(ConfirmDialogComponent, {
      data: {
        title: 'Eliminar Producto',
        message: `¿Estás seguro que deseás eliminar "${product.name}"? Esta acción no se puede deshacer.`,
        confirmText: 'Eliminar',
        cancelText: 'Cancelar'
      }
    });

    ref.afterClosed().subscribe(confirmed => {
      if (confirmed) {
        this.productService.deleteProduct(product.id).subscribe({
          next: () => {
            this.snackBar.open('Producto eliminado', 'Cerrar', { duration: 3000 });
            if (this.products.length === 1 && this.currentPage > 0) {
              this.currentPage -= 1;
            }
            this.loadProducts();
          },
          error: (err) => {
            this.snackBar.open(
              err.error?.message || 'Error al eliminar el producto',
              'Cerrar',
              { duration: 3000 }
            );
          }
        });
      }
    });
  }

  goBack(): void {
    this.router.navigate(['/principal']);
  }

  getStockStatus(stock: number | undefined): 'unknown' | 'out' | 'low' | 'in' {
    if (stock === undefined || stock === null) return 'unknown';
    if (stock === 0) return 'out';
    if (stock < 10) return 'low';
    return 'in';
  }

  getStockLabel(stock: number | undefined): string {
    if (stock === undefined || stock === null) return 'Sin info';
    if (stock === 0) return 'Sin stock';
    if (stock < 10) return `Solo ${stock} disponibles`;
    return `${stock} en stock`;
  }

  formatPrice(price: number): string {
    return price?.toLocaleString('es-AR', {
      style: 'currency',
      currency: 'ARS',
      minimumFractionDigits: 2
    }) ?? '-';
  }

  getProductImageUrl(product: Product): string | null {
    return this.productService.getImageUrl(product.image);
  }

  get activeFiltersCount(): number {
    let count = 0;

    if (this.searchControl.value.trim()) {
      count += 1;
    }
    if (this.categoryFilter.value !== 'all') {
      count += 1;
    }
    if (this.stockFilter.value !== 'all') {
      count += 1;
    }
    if (this.sortControl.value !== 'createdAt:desc') {
      count += 1;
    }

    return count;
  }
}
